#!/usr/bin/env python3
"""Quelle der Aufgaben (Python-Trainer). Erzeugt daten/aufgaben.json:  python3 tools/pipeline/aufgaben_quelle.py
Typen: predict (Ausgabe vorhersagen), gap (Lückencode), bug (Fehler finden und korrigieren), puzzle (Zeilen ordnen), code (selbst programmieren).
Parameter: <<name>> im Text/Code; vars = zusammengehörige Wertelisten (gleicher Index wird gemeinsam gewählt).
Erwartete Ausgaben werden zur Laufzeit aus dem Code bzw. der Referenzlösung (ref) berechnet; tests = Liste von Eingabe-Listen (input())."""
import json, os
H = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
T = []
def add(id, kap, typ, lvl, titel, **k):
    d = dict(id=id, kap=kap, typ=typ, lvl=lvl, titel=titel); d.update(k); T.append(d)
def P(id, kap, lvl, titel, code, hints, **k): add(id, kap, 'predict', lvl, titel, code=code, hints=hints, **k)
def G(id, kap, lvl, titel, code, ans, hints, **k): add(id, kap, 'gap', lvl, titel, code=code, ans=ans, hints=hints, **k)
def B(id, kap, lvl, titel, text, code, ref, hints, **k): add(id, kap, 'bug', lvl, titel, text=text, code=code, ref=ref, hints=hints, **k)
def Z(id, kap, lvl, titel, text, lines, hints, **k): add(id, kap, 'puzzle', lvl, titel, text=text, lines=lines, hints=hints, **k)
def C(id, kap, lvl, titel, text, ref, hints, **k): add(id, kap, 'code', lvl, titel, text=text, ref=ref, hints=hints, **k)

# ---------------- Kapitel 1: Ausgabe mit print ----------------
P('a001', 1, 1, 'print mit Text', 'print("Hallo <<n>>!")', ['print gibt den Text zwischen den Anführungszeichen aus.', 'Die Anführungszeichen selbst werden nicht mit ausgegeben.'], vars={'n': ['Welt', 'Felix', 'Sophia', 'Python']})
P('a002', 1, 1, 'Mehrere print-Zeilen', 'print("<<a>>")\nprint("<<b>>")\nprint("<<c>>")', ['Jedes print beginnt in einer neuen Zeile.'], vars={'a': ['Eins', 'Rot', 'Montag'], 'b': ['Zwei', 'Gelb', 'Dienstag'], 'c': ['Drei', 'Blau', 'Mittwoch']})
P('a003', 1, 2, 'print mit Komma', 'print("Ich bin", <<z>>, "Jahre alt")', ['Zwischen den durch Komma getrennten Teilen setzt print automatisch ein Leerzeichen.', 'Zahlen brauchen keine Anführungszeichen.'], vars={'z': ['12', '13', '11', '14']})
P('a004', 1, 2, 'Zeilenumbruch und sep', 'print("<<a>>\\n<<b>>")\nprint("x", "y", "z", sep="<<s>>")', ['\\n ist ein Zeilenumbruch.', 'sep legt fest, was zwischen den Teilen steht (normal: ein Leerzeichen).'], vars={'a': ['Hallo', 'Oben', 'Eins'], 'b': ['Welt', 'Unten', 'Zwei'], 's': ['-', '+', '/']})
P('a005', 1, 3, 'print mit end', 'print("Eins", end=" ")\nprint("Zwei", end=" ")\nprint("Drei")\nprint("Vier")', ['end legt fest, was am Ende der Ausgabe steht (normal: ein Zeilenumbruch).', 'Hier steht nach "Eins" und "Zwei" nur ein Leerzeichen – die nächste Ausgabe geht in derselben Zeile weiter.'])
G('a006', 1, 1, 'print-Befehl', '___("Python macht Spaß!")', ['print'], ['Welcher Befehl gibt Text aus?'], text='Ergänze den fehlenden Befehl, damit der Text ausgegeben wird.')
G('a007', 1, 2, 'sep ergänzen', 'print("a", "b", "c", ___="-")', ['sep'], ['Das Wort steht zwischen den Teilen der Ausgabe.', 'Es hat drei Buchstaben und beginnt mit s.'], text='Ergänze den Namen des Parameters, damit zwischen den Buchstaben ein Strich steht.')
B('a008', 1, 1, 'Groß- und Kleinschreibung', 'Das Programm soll „Guten Morgen“ ausgeben.', 'Print("Guten Morgen")', 'print("Guten Morgen")', ['Python unterscheidet Groß- und Kleinschreibung.', 'Der Befehl heißt print – komplett klein geschrieben.'])
B('a009', 1, 2, 'Anführungszeichen fehlt', 'Das Programm soll zwei Zeilen ausgeben.', 'print("Das ist ein Test)\nprint("Zweite Zeile")', 'print("Das ist ein Test")\nprint("Zweite Zeile")', ['Jeder Text braucht Anführungszeichen am Anfang UND am Ende.', 'Schau dir die erste Zeile genau an.'])
Z('a010', 1, 1, 'Countdown', 'Bringe die Zeilen in die richtige Reihenfolge: Das Programm zählt herunter.', ['print("3")', 'print("2")', 'print("1")', 'print("Los!")'], ['Der Countdown beginnt bei der größten Zahl.'])
Z('a011', 1, 2, 'Gruß und Abschied', 'Bringe die Zeilen in die richtige Reihenfolge.', ['print("Hallo <<a>>!")', 'print("Hallo <<b>>!")', 'print("Tschüss!")'], ['Die Ausgabe soll genau in dieser Reihenfolge erscheinen (siehe Erwartete Ausgabe).'], vars={'a': ['Felix', 'Anna', 'Max'], 'b': ['Sophia', 'Ben', 'Lena']})
C('a012', 1, 1, 'Einen Satz ausgeben', 'Schreibe ein Programm, das den Satz **<<satz>>** ausgibt.', 'print("<<satz>>")', ['Benutze print und setze den Satz in Anführungszeichen.'], vars={'satz': ['Ich lerne Python', 'Heute ist ein guter Tag', 'Python ist cool', 'Hallo Welt']})
C('a013', 1, 2, 'Zwei Zeilen mit einem print', 'Gib mit **nur einem** `print`-Befehl zwei Zeilen aus: zuerst `<<a>>`, in der nächsten Zeile `<<b>>`.', 'print("<<a>>\\n<<b>>")', ['Ein Zeilenumbruch wird im Text mit \\n geschrieben.'], vars={'a': ['Hallo', 'Guten Tag', 'Eins'], 'b': ['Welt', 'Python', 'Zwei']}, need=[{'re': '^(?![\\s\\S]*print[\\s\\S]*print)', 'msg': 'Benutze nur einen einzigen print-Befehl.'}])
C('a014', 1, 3, 'Muster ausgeben', 'Gib dieses Muster aus:\n```\n*****\n*   *\n*****\n```', 'print("*****")\nprint("*   *")\nprint("*****")', ['Drei Zeilen, also drei print-Befehle.', 'In der mittleren Zeile stehen drei Leerzeichen.'])

