# ---------------- Kapitel 7: Funktionen ----------------
P('a106', 7, 1, 'Funktion aufrufen', 'def hallo():\n    print("Hallo!")\n\nhallo()\nhallo()', ['def legt die Funktion nur fest, ausgeführt wird sie erst beim Aufruf.', 'Hier wird sie zweimal aufgerufen.'])
P('a107', 7, 1, 'Parameter', 'def gruss(name):\n    print("Hallo", name)\n\ngruss("<<a>>")\ngruss("<<b>>")', ['Der Parameter name bekommt beim Aufruf den Wert in den Klammern.'], vars={'a': ['Felix', 'Anna', 'Ben'], 'b': ['Sophia', 'Max', 'Lena']})
P('a108', 7, 2, 'return', 'def quadrat(x):\n    return x * x\n\nprint(quadrat(<<a>>) + quadrat(<<b>>))', ['return gibt einen Wert an die Stelle des Aufrufs zurück.', 'Rechne erst die beiden Aufrufe aus, dann addiere.'], vars={'a': ['2', '3', '5'], 'b': ['3', '4', '1']})
P('a109', 7, 2, 'return oder print?', 'def f(x):\n    print(x + 1)\n\ny = f(<<a>>)\nprint(y)', ['Die Funktion gibt etwas aus, hat aber kein return.', 'Ohne return liefert eine Funktion den Wert None zurück.'], vars={'a': ['4', '10', '99']})
P('a110', 7, 3, 'Standardwert', 'def potenz(basis, exp=2):\n    return basis ** exp\n\nprint(potenz(<<a>>))\nprint(potenz(<<a>>, 3))', ['Wird exp nicht angegeben, gilt der Standardwert 2.'], vars={'a': ['3', '2', '5']})
P('a111', 7, 3, 'Variablen in Funktionen', 'x = 10\n\ndef f():\n    x = 5\n    return x\n\nprint(f())\nprint(x)', ['Das x in der Funktion ist eine eigene, lokale Variable.', 'Das äußere x bleibt unverändert.'])
G('a112', 7, 1, 'Funktion definieren', '___ hallo():\n    print("Hallo!")\n\nhallo()', ['def'], ['Mit welchem Schlüsselwort beginnt eine Funktion?'], text='Ergänze das Schlüsselwort.')
G('a113', 7, 2, 'Rückgabewert', 'def doppelt(x):\n    ___ x * 2\n\nprint(doppelt(21))', ['return'], ['Der Wert soll aus der Funktion herausgegeben werden.'], text='Ergänze das Schlüsselwort, damit die Funktion einen Wert zurückgibt.')
G('a114', 7, 3, 'Zweiter Parameter', 'def addiere(a, ___):\n    return a + b\n\nprint(addiere(3, 4))', ['b'], ['Im Funktionskörper wird ein Name b benutzt.'], text='Ergänze den fehlenden Parameter.')
