B('a116', 7, 2, 'Kein return', 'Die Funktion soll das Quadrat **zurückgeben**; das Programm soll 26 ausgeben.', 'def quadrat(x):\n    print(x * x)\n\nergebnis = quadrat(5)\nprint(ergebnis + 1)', 'def quadrat(x):\n    return x * x\n\nergebnis = quadrat(5)\nprint(ergebnis + 1)', ['print zeigt nur etwas an, gibt aber nichts zurück.', 'Mit return kann man mit dem Ergebnis weiterrechnen.'])
B('a117', 7, 3, 'Zu wenige Argumente', 'Das Programm soll die Fläche eines Rechtecks mit den Seiten 5 und 3 ausgeben (15).', 'def flaeche(l, b):\n    return l * b\n\nprint(flaeche(5))', 'def flaeche(l, b):\n    return l * b\n\nprint(flaeche(5, 3))', ['Die Funktion braucht zwei Angaben.', 'TypeError: Es fehlt ein Argument beim Aufruf.'])
Z('a118', 7, 2, 'Verdoppeln', 'Bringe die Zeilen in die richtige Reihenfolge.', ['def verdopple(x):', '    return x * 2', 'print(verdopple(<<a>>))'], ['Erst die Funktion definieren, dann aufrufen.', 'Die Zeile mit return gehört eingerückt unter def.'], vars={'a': ['21', '5', '60']})
Z('a119', 7, 3, 'Größere Zahl', 'Bringe die Zeilen in die richtige Reihenfolge (auf die Einrückung achten).', ['def groesser(a, b):', '    if a > b:', '        return a', '    return b', 'print(groesser(<<a>>, <<b>>))'], ['Die Funktion gibt a zurück, wenn a größer ist, sonst b.'], vars={'a': ['3', '10', '7'], 'b': ['9', '4', '7']})
C('a120', 7, 1, 'Funktion gruss', 'Schreibe eine Funktion `gruss(name)`, die `Hallo <name>!` ausgibt (bei Felix: `Hallo Felix!`).', 'def gruss(name):\n    print("Hallo " + name + "!")', ['Beginne mit def gruss(name):', 'In der Funktion steht ein print.'], append='gruss("Felix")\ngruss("Sophia")', need=[{'re': 'def\\s+gruss\\s*\\(', 'msg': 'Definiere eine Funktion namens gruss.'}])
C('a121', 7, 2, 'Funktion quadrat', 'Schreibe eine Funktion `quadrat(x)`, die das Quadrat von x **zurückgibt** (mit `return`).', 'def quadrat(x):\n    return x * x', ['Die Funktion braucht einen Parameter und ein return.'], append='print(quadrat(4))\nprint(quadrat(-3))\nprint(quadrat(0))', need=[{'re': 'return', 'msg': 'Benutze return.'}])
C('a122', 7, 2, 'Mittelwert', 'Schreibe eine Funktion `mittelwert(a, b)`, die den Mittelwert der beiden Zahlen zurückgibt.', 'def mittelwert(a, b):\n    return (a + b) / 2', ['Mittelwert = (a + b) geteilt durch 2.', 'Denke an die Klammern.'], append='print(mittelwert(4, 6))\nprint(mittelwert(1, 2))\nprint(mittelwert(10, 10))')
C('a123', 7, 3, 'ist_gerade', 'Schreibe eine Funktion `ist_gerade(zahl)`, die `True` zurückgibt, wenn die Zahl gerade ist, sonst `False`.', 'def ist_gerade(zahl):\n    return zahl % 2 == 0', ['Der Vergleich zahl % 2 == 0 liefert schon True oder False.'], append='print(ist_gerade(4))\nprint(ist_gerade(7))\nprint(ist_gerade(0))')
C('a124', 7, 3, 'Maximum von drei', 'Schreibe eine Funktion `maximum(a, b, c)`, die die größte der drei Zahlen zurückgibt. Benutze **nicht** `max`.', 'def maximum(a, b, c):\n    if a >= b and a >= c:\n        return a\n    if b >= c:\n        return b\n    return c', ['Vergleiche mit if und and.', 'Bei return endet die Funktion sofort.'], append='print(maximum(1, 5, 3))\nprint(maximum(9, 2, 4))\nprint(maximum(3, 3, 3))\nprint(maximum(-1, -5, -3))', need=[{'re': 'max\\s*\\(', 'not': True, 'msg': 'Benutze nicht max(), sondern if.'}])
C('a125', 7, 3, 'Fakultät', 'Schreibe eine Funktion `fakultaet(n)`, die n! = 1 · 2 · … · n zurückgibt (0! ist 1).', 'def fakultaet(n):\n    ergebnis = 1\n    for i in range(1, n + 1):\n        ergebnis = ergebnis * i\n    return ergebnis', ['Starte mit ergebnis = 1 und multipliziere in einer Schleife.', 'Für n = 0 läuft die Schleife gar nicht – das Ergebnis bleibt 1.'], append='print(fakultaet(5))\nprint(fakultaet(1))\nprint(fakultaet(0))\nprint(fakultaet(6))')

